#include <bits/stdc++.h>
using namespace std;

class DStress2_Variant1 {
public:
    int INF = INT_MAX / 3;

    int solve(const string& s_str) {
        vector<int> vPos, kPos, otherPos;
        for (int i = 0; i < (int)s_str.size(); i++) {
            if (s_str[i] == 'V') vPos.push_back(i);
            else if (s_str[i] == 'K') kPos.push_back(i);
            else otherPos.push_back(i);
        }
        int vSize = (int)vPos.size();
        int kSize = (int)kPos.size();
        int oSize = (int)otherPos.size();

        vector<vector<vector<vector<int>>>> dp(2,
            vector<vector<vector<int>>>(vSize + 1,
                vector<vector<int>>(kSize + 1,
                    vector<int>(oSize + 1, INF)
                )
            )
        );

        dp[0][0][0][0] = 0;

        auto count_in_list = [&](int index, int start, const vector<int>& positions) {
            int ans = 0;
            for (int i = start; i < (int)positions.size(); i++) {
                if (positions[i] < index) ans++;
            }
            return ans;
        };

        for (int V = 0; V <= vSize; V++) {
            for (int K = 0; K <= kSize; K++) {
                for (int O = 0; O <= oSize; O++) {
                    for (int last = 0; last < 2; last++) {
                        int cur = dp[last][V][K][O];
                        if (cur == INF) continue;
                        if (V < vSize) {
                            int cost = cur + count_in_list(vPos[V], K, kPos) + count_in_list(vPos[V], O, otherPos);
                            if (cost < dp[1][V + 1][K][O]) {
                                dp[1][V + 1][K][O] = cost;
                            }
                        }
                        if (K < kSize && last == 0) {
                            int cost = cur + count_in_list(kPos[K], V, vPos) + count_in_list(kPos[K], O, otherPos);
                            if (cost < dp[0][V][K + 1][O]) {
                                dp[0][V][K + 1][O] = cost;
                            }
                        }
                        if (O < oSize) {
                            int cost = cur + count_in_list(otherPos[O], V, vPos) + count_in_list(otherPos[O], K, kPos);
                            if (cost < dp[0][V][K][O + 1]) {
                                dp[0][V][K][O + 1] = cost;
                            }
                        }
                    }
                }
            }
        }
        return min(dp[0][vSize][kSize][oSize], dp[1][vSize][kSize][oSize]);
    }

    void run() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        int n;
        string s;
        cin >> n >> s;
        cout << solve(s) << "\n";
    }
};

int main() {
    DStress2_Variant1 solver;
    solver.run();
    return 0;
}

